"""New practice problems (written for this app, NOT from the worksheets). Each uses a different idea; expected outputs are computed from `fn`.
Row: (topic, id, title uz, title en, statement uz, statement en, fn, cases)  — first 2 cases are examples, the rest hidden."""
def longest(n, *v):
    b = c = 0
    for x in v: c = c + 1 if x == 1 else 0; b = max(b, c)
    return b
def pool(c):
    v = m = 0
    while v < c:
        v += 7; m += 1
        if v < c: v -= 2
    return m
def grow(p, t):
    y = 0
    while p < t: p *= 1.1; y += 1
    return y
def save(s, r):
    for _ in range(r): s *= 1.1
    return s
def pin(*a):
    w = 0
    for x in a:
        if x == 1234: return 'Ochildi'
        w += 1
        if w == 3: return 'Bloklandi'
def grade(n): return 'A' if n >= 90 else 'B' if n >= 75 else 'C' if n >= 60 else 'D' if n >= 40 else 'F'
